"""Sitting and leaning with a belt tracker on the side, three ways of handling the waist:

  rigid    — final = real · offset (the tracker's tilt goes straight to the avatar's pelvis)
  level    — the sideways roll is always removed (the «balanced» mode of 2026-11-14 03:51)
  sitfix   — only the roll the tracker picks up FROM SITTING is removed (learned once: «я сиджу рівно»)

The flesh on the side of the hip pushes the tracker over when the hip bends (sitting): measured +7.6°
for her. Real sideways leans roll the pelvis for real and must reach the avatar.
  .venv/bin/python -I sim/sitting.py
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "app"))
sys.path.insert(0, str(Path(__file__).resolve().parent))
import numpy as np

from fbtcal import body as B
from humanoid import Body, mat_q, rot_x, rot_z

FLESH_ROLL = np.radians(7.6)   # extra sideways tilt of a side tracker at full sitting (measured)
SIT_PITCH = np.radians(25)     # pelvis tilt when sitting


def tracker(body, pelvis_pitch, pelvis_roll, rng):
    """The side tracker's real pose for a pelvis tilted back by pitch and sideways by roll."""
    rp = rot_x(pelvis_pitch) @ rot_z(pelvis_roll)
    sit = min(1.0, max(0.0, pelvis_pitch / SIT_PITCH))
    flesh = rot_z(FLESH_ROLL * sit)            # the hip flesh rolls the tracker over (about forward)
    pos = body.pelvis0 + rp @ body.waist_pos
    rot = rp @ flesh @ body.waist_rot
    d = rng.normal(0, np.radians(0.3), 3)
    return pos, mat_q(rot_x(d[0]) @ rot_z(d[2]) @ rot)


def roll_of(q):
    m = B.pose_to_mat(np.zeros(3), q)[:, :3]
    return np.degrees(np.arcsin(np.clip(m[:, 0][1], -1, 1)))


def pitch_of(q):
    m = B.pose_to_mat(np.zeros(3), q)[:, :3]
    return np.degrees(np.arcsin(np.clip(-m[:, 2][1], -1, 1)))


def main():
    rng = np.random.default_rng(1)
    body = Body(waist_mount=(0.16, 0.05, -0.02))
    # calibration standing straight: final = yaw-aligned upright
    real0 = tracker(body, 0.0, 0.0, rng)
    off = B.compose(B.inverse(real0), (body.pelvis0, np.array([1.0, 0, 0, 0])))
    # learning the sitting bias: she sits upright once
    sit_real = tracker(body, SIT_PITCH, 0.0, rng)
    sit_final = B.compose(sit_real, off)
    bias, p_sit = roll_of(sit_final[1]), pitch_of(sit_final[1])
    print(f"learned while sitting upright: roll bias {bias:+.1f}°, pelvis tilt {p_sit:.0f}°\n")
    cases = [("standing straight", 0, 0), ("standing, lean left 6°", 0, -6), ("standing, lean right 6°", 0, 6),
             ("sitting straight", 25, 0), ("sitting, lean left 6°", 25, -6), ("sitting, lean right 6°", 25, 6),
             ("half sitting (12°)", 12, 0)]
    print(f"{'':26s}{'true pelvis roll':>17s}{'rigid':>9s}{'level':>9s}{'sitfix':>9s}   (avatar pelvis roll error, °)")
    worst = {"rigid": 0, "level": 0, "sitfix": 0}
    for name, pitch, roll in cases:
        real = tracker(body, np.radians(pitch), np.radians(roll), rng)
        rigid = B.compose(real, off)
        level = B.level_roll(real[0], rigid)
        fixed = B.sit_fix(real[0], rigid, np.radians(bias), np.radians(p_sit))
        errs = {k: roll_of(v[1]) - roll for k, v in (("rigid", rigid), ("level", level), ("sitfix", fixed))}
        for k, v in errs.items():
            worst[k] = max(worst[k], abs(v))
        print(f"{name:26s}{roll:>+16.0f}°" + "".join(f"{errs[k]:>+8.1f}°" for k in ("rigid", "level", "sitfix")))
    print("\nworst error: " + ", ".join(f"{k} {v:.1f}°" for k, v in worst.items()))


if __name__ == "__main__":
    main()
